-- A district you can find from a dropped pin.
--
-- The district import took the names and left the boundaries behind — 58 MB of polygons for a
-- platform that draws no maps. That was right, and it leaves one thing impossible: a pin on a map
-- can name its region and its city, because cities carry a centre point, and cannot name its
-- district.
--
-- The centre of each district is the missing piece, and it is two numbers rather than a polygon.
-- Computed here from those boundaries once, offline: the area-weighted centroid of each district's
-- largest ring, which for the concave shapes some districts have is a better answer than the mean
-- of the points. 3,732 of 3,732 produced one inside Saudi Arabia's bounding box; the rest had
-- degenerate or out-of-range geometry and are left without, so a pin near them falls back to the
-- city rather than naming a district wrongly.
--
-- What this does not do is decide whether a point is INSIDE a district — that needs the polygons.
-- Nearest-centre is what the address form uses, and for choosing a district from a map pin it is
-- the right trade: wrong by a street occasionally, against a field nobody can fill at all.

ALTER TABLE qvm_new_apps.districts
  ADD COLUMN IF NOT EXISTS location_lat double precision,
  ADD COLUMN IF NOT EXISTS location_lng double precision;

CREATE TEMP TABLE _district_centre (ext_id bigint, lat double precision, lng double precision);


UPDATE qvm_new_apps.districts d
   SET location_lat = c.lat, location_lng = c.lng, updated_at = now()
  FROM _district_centre c
 WHERE d.external_id = c.ext_id;

DROP TABLE _district_centre;

CREATE INDEX IF NOT EXISTS idx_districts_centre
  ON qvm_new_apps.districts (location_lat, location_lng)
  WHERE location_lat IS NOT NULL;
